package android.widget;public class SeekBar extends android.view.View {public int min,max,progress;public OnSeekBarChangeListener listener;public SeekBar(android.content.Context c){super(c);}public interface OnSeekBarChangeListener{void onProgressChanged(SeekBar s,int p,boolean u);void onStartTrackingTouch(SeekBar s);void onStopTrackingTouch(SeekBar s);}public void setOnSeekBarChangeListener(OnSeekBarChangeListener l){listener=l;}public void setMin(int m){min=m;}public void setMax(int m){max=m;}public void setProgress(int p){progress=p;if(listener!=null)listener.onProgressChanged(this,p,false);}}